#!/usr/bin/env node
// Turns every scenarios/<company>/<day>.yaml into typed TypeScript the game can import,
// after checking it in three ways:
//   1. against scenarios/scenario.schema.json,
//   2. that every room, person, thing, asset and threat it mentions exists,
//   3. that the texts are easy to read (Flesch Reading Ease 60+, no sentence of 20+ words).
//
//   node scripts/build-scenarios.mjs           # check and write shared/src/scenarios.generated.ts
//   node scripts/build-scenarios.mjs --check   # only check; write nothing
//
// The generated file is not kept in git (it is in .gitignore). `npm run dev`, `build`, `check`, `test`
// and `test:e2e` all write it first, so it is always up to date when it is used.

import { readFileSync, writeFileSync, readdirSync, statSync } from "node:fs";
import { join, relative, dirname } from "node:path";
import { fileURLToPath } from "node:url";
import { parse } from "yaml";
import Ajv2020 from "ajv/dist/2020.js";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const scenarioDir = join(root, "scenarios");
const outFile = join(root, "shared", "src", "scenarios.generated.ts");
const checkOnly = process.argv.includes("--check");

const MIN_FLESCH = 60;
const MAX_WORDS = 20;

const schema = JSON.parse(readFileSync(join(scenarioDir, "scenario.schema.json"), "utf8"));
const validate = new Ajv2020({ allErrors: true, strict: false }).compile(schema);

const files = readdirSync(scenarioDir)
  .filter((d) => statSync(join(scenarioDir, d)).isDirectory())
  .flatMap((d) => readdirSync(join(scenarioDir, d)).filter((f) => f.endsWith(".yaml")).map((f) => join(scenarioDir, d, f)))
  .sort();

const problems = [];
const scenarios = {};

for (const file of files) {
  const name = relative(root, file);
  let data;
  try {
    data = parse(readFileSync(file, "utf8"));
  } catch (e) {
    problems.push(`${name}: not valid YAML — ${e.message}`);
    continue;
  }

  if (!validate(data)) {
    for (const err of validate.errors) problems.push(`${name}: ${err.instancePath || "(top)"} ${err.message}`);
    continue;
  }

  problems.push(...checkReferences(data).map((p) => `${name}: ${p}`));
  const read = readability(data);
  if (read.flesch < MIN_FLESCH) problems.push(`${name}: Flesch Reading Ease is ${read.flesch}; aim for ${MIN_FLESCH} or more`);
  for (const s of read.long) problems.push(`${name}: sentence of ${MAX_WORDS}+ words: "${s}"`);

  if (scenarios[data.id]) problems.push(`${name}: duplicate scenario id "${data.id}"`);
  scenarios[data.id] = data;
  console.log(`✓ ${name} · ${data.title} · Flesch ${read.flesch}, ${read.sentences} sentences`);
}

if (problems.length) {
  console.error(`\n${problems.length} problem(s):`);
  for (const p of problems) console.error(`  ✗ ${p}`);
  process.exit(1);
}

const output =
  `// Generated by scripts/build-scenarios.mjs from scenarios/**/*.yaml — do not edit by hand.\n` +
  `// Scenario content is licensed CC BY-SA 4.0 (see LICENSE-CONTENT.md).\n` +
  `import type { Scenario } from "./scenario";\n\n` +
  `export const scenarios: Record<string, Scenario> = ${JSON.stringify(scenarios, null, 2)};\n`;

if (checkOnly) {
  console.log("✓ scenarios are valid");
} else {
  writeFileSync(outFile, output);
  console.log(`Wrote ${relative(root, outFile)} with ${Object.keys(scenarios).length} scenario(s).`);
}

function checkReferences(d) {
  const errs = [];
  const ids = (list) => new Set(list.map((x) => x.id));
  const rooms = ids(d.map.rooms);
  const zones = ids(d.map.zones);
  const people = ids(d.people);
  const things = ids(d.things);
  const assets = ids(d.assets);
  const threats = ids(d.threats);
  const places = new Set([...rooms, ...zones]);
  const need = (set, id, what) => {
    if (!set.has(id)) errs.push(`${what} "${id}" does not exist`);
  };

  for (const r of d.map.rooms) {
    need(zones, r.zone, `zone of room ${r.id}`);
    const [x, y, w, h] = r.rect;
    if (x < 0 || y < 0 || x + w > d.map.width || y + h > d.map.height) errs.push(`room ${r.id} is outside the map`);
  }
  const floors = new Set((d.map.floors ?? []).map((f) => f.id));
  for (const f of d.map.floors ?? []) {
    const [x, y, w, h] = f.rect;
    if (x < 0 || y < 0 || x + w > d.map.width || y + h > d.map.height) errs.push(`floor ${f.id} is outside the map`);
    if (rooms.has(f.id)) errs.push(`floor ${f.id} has the same id as a room`);
  }
  const places2 = new Set([...rooms, ...floors]);
  for (const door of d.map.doors ?? []) {
    need(places2, door.a, "door side a");
    need(places2, door.b, "door side b");
  }
  if ((d.map.doors ?? []).length) {
    const start = d.map.rooms.find((r) => r.start)?.id ?? d.map.rooms[0].id;
    const seen = new Set([start]);
    for (let grew = true; grew; ) {
      grew = false;
      for (const door of d.map.doors) {
        for (const [from, to] of [[door.a, door.b], [door.b, door.a]]) if (seen.has(from) && !seen.has(to)) (seen.add(to), (grew = true));
      }
    }
    for (const r of rooms) if (!seen.has(r)) errs.push(`room ${r} cannot be reached through the doors from the start room`);
  }
  for (const s of d.story) need(people, s.speaker, "story speaker");
  for (const p of d.people) {
    need(rooms, p.room, `room of ${p.id}`);
    for (const t of p.topics) for (const a of t.reveals ?? []) need(assets, a, `asset revealed by ${p.id}`);
  }
  for (const t of d.things) need(rooms, t.room, `room of thing ${t.id}`);
  for (const a of d.assets) for (const z of a.lives_in) need(places, z, `place of asset ${a.id}`);
  for (const f of d.flows ?? []) {
    for (const k of ["from", "to", "via"]) if (f[k]) need(places, f[k], `flow ${k}`);
    for (const a of f.carries) need(assets, a, "asset in flow");
  }
  for (const t of d.threats) {
    if (!things.has(t.target) && !rooms.has(t.target)) errs.push(`threat ${t.id} targets "${t.target}", which is not a thing or room`);
  }
  for (const p of d.day.problems) need(threats, p, "day problem");
  for (const e of d.day.events) need(people, e.from, "event sender");
  for (const c of d.day.clues) {
    need(rooms, c.room, "clue room");
    need(threats, c.points_to, "clue threat");
  }
  if (!d.day.final_choice.options.some((o) => o.best)) errs.push("final choice has no option marked best");
  return errs;
}

function readability(d) {
  const keys = new Set(["text", "hello", "ask", "answer", "goal", "question", "result", "closer", "summary", "alert"]);
  const texts = [];
  const walk = (x) => {
    if (Array.isArray(x)) x.forEach(walk);
    else if (x && typeof x === "object")
      for (const [k, v] of Object.entries(x)) {
        if (keys.has(k) && typeof v === "string") texts.push(v);
        else walk(v);
      }
  };
  walk(d);
  const all = texts.join(" ");
  const sentences = all.split(/[.!?]+/).map((s) => s.trim()).filter(Boolean);
  const words = all.match(/[A-Za-z'’]+/g) ?? [];
  const syllables = words.reduce((n, w) => n + countSyllables(w), 0);
  const flesch = Math.round(206.835 - 1.015 * (words.length / sentences.length) - 84.6 * (syllables / words.length));
  const long = sentences.filter((s) => s.split(/\s+/).length >= MAX_WORDS);
  return { flesch, long, sentences: sentences.length };
}

function countSyllables(word) {
  const w = word.toLowerCase().replace(/[^a-z]/g, "");
  if (!w) return 0;
  let n = (w.match(/[aeiouy]+/g) ?? []).length;
  if (w.endsWith("e") && n > 1 && !w.endsWith("le")) n--;
  return Math.max(n, 1);
}
